/// Fills the editor colors from the scheme; unmapped fields keep `e`'s value.
fn editor(mut e: EditorColors) -> EditorColors {
    e.background = px(0x1E1F22FF); // TEXT.bg
    e.text = px(0xBCBEC4FF); // TEXT.fg
    e.caret = px(0xCED0D6FF); // CARET_COLOR
    e.caret_row = px(0x26282EFF); // CARET_ROW_COLOR
    e.line_number = px(0x4B5059FF); // LINE_NUMBERS_COLOR
    e.line_number_caret = px(0xA1A3ABFF); // LINE_NUMBER_ON_CARET_ROW_COLOR
    e.selection = px(0x214283FF); // SELECTION_BACKGROUND
    e.background_panel = px(0x2B2D30FF); // DOCUMENTATION_COLOR
    e.search_result = px(0x114957FF); // TEXT_SEARCH_RESULT_ATTRIBUTES.bg
    e.rename_occurrence = px(0x373B39FF); // IDENTIFIER_UNDER_CARET_ATTRIBUTES.bg
    e.matched_brace = px(0x43454AFF); // MATCHED_BRACE_ATTRIBUTES.bg
    e.indent_guide = px(0x313438FF); // INDENT_GUIDE
    e.error_effect = px(0xFA6675FF); // ERRORS_ATTRIBUTES.effect
    e.warning_effect = px(0xF2C55CFF); // WARNING_ATTRIBUTES.effect
    e.weak_warning_effect = px(0x857042FF); // INFO_ATTRIBUTES.effect
    e.breakpoint_line = px(0x40252BFF); // BREAKPOINT_ATTRIBUTES.bg
    e.execution_line = px(0x2A5091FF); // EXECUTIONPOINT_ATTRIBUTES.bg
    e.inline_value = px(0x666D75FF); // DEBUGGER_INLINED_VALUES.fg
    e.error_stripe = px(0xD64D5BFF); // ERRORS_ATTRIBUTES.stripe
    e.warning_stripe = px(0xC29E4AFF); // WARNING_ATTRIBUTES.stripe
    e.string = px(0x6AAB73FF); // DEFAULT_STRING.fg
    e.number = px(0x2AACB8FF); // DEFAULT_NUMBER.fg
    e.keyword = px(0xCF8E6DFF); // DEFAULT_KEYWORD.fg
    e.constant = px(0xC77DBBFF); // DEFAULT_CONSTANT.fg
    e.type_name = px(0x16BAACFF); // TYPE_PARAMETER_NAME_ATTRIBUTES.fg
    e.annotation = px(0xB3AE60FF); // DEFAULT_METADATA.fg
    e.property = px(0xC77DBBFF); // DEFAULT_INSTANCE_FIELD.fg
    e.punctuation = px(0xBCBEC4FF); // DEFAULT_COMMA.fg
    e.comment = px(0x7A7E85FF); // DEFAULT_LINE_COMMENT.fg
    e.tag = px(0xD5B778FF); // XML_TAG_NAME.fg
    e.attribute = px(0xBCBEC4FF); // XML_ATTRIBUTE_NAME.fg
    e.variable = px(0x56A8F5FF); // DEFAULT_FUNCTION_DECLARATION.fg
    e.invalid = px(0xF75464FF); // BAD_CHARACTER.fg
    // Kept at the measured value: search_result_current.
    e
}
